//! Cargo-driven `wmiutils.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is wmiutils-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6c870000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe41000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe41000000u64)),
        o => panic!("wmiutils-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/wmiutils/wmiutils_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:oldnames", "import:oleaut32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll"],
        "x86_64" => &["dll/win32/wmiutils/wmiutils_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:oldnames", "import:oleaut32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll"],
        "aarch64" => &["dll/win32/wmiutils/wmiutils_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:oldnames", "import:oleaut32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("wmiutils-rust")
        .spec2def("dll/win32/wmiutils/wmiutils.spec", "wmiutils.dll")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
